const grupoConsultaGastronomica = (consulta = '') => {
    const limpio = normalizarBusquedaGastronomica(consulta);
    if (!limpio)
        return null;
    if (/acompanamientos? rotativos?|guarniciones? rotativas?|sequencia de acompanhamentos|rotating sides/.test(limpio))
        return 'rotativos';
    if (/frutos do mar|frutos del mar|seafood/.test(limpio))
        return 'mariscos';
    if (/cafe da manha|coffee and breakfast/.test(limpio))
        return 'cafe';
    if (/com vista|con vista|with a view|frente (al|ao) mar/.test(limpio))
        return 'vista';
    const palabras = limpio.split(/\s+/);
    return palabras.map(p => ALIAS_BUSQUEDA_GASTRONOMICA[p]).find(Boolean) || null;
};
const coincideIntencionGastronomica = (item, intencion) => {
    if (!intencion || intencion === 'todos')
        return true;
    const tipos = item.tipos || [];
    const texto = normalizarBusquedaGastronomica(`${item.nombre} ${item.barrio} ${item.destaque} ${tipos.join(' ')}`);
    if (intencion === 'almuerzo')
        return !(/bar nocturno|discoteca|solo cena/.test(texto)) && !(tipos.length === 1 && tipos.includes('madrugada'));
    if (intencion === 'cena')
        return !(/solo desayuno|cafeteria historica/.test(texto)) && !(tipos.length === 1 && tipos.includes('cafe'));
    if (intencion === 'rotativos')
        return tipos.some(t => ['carnes', 'buffet'].includes(t)) || /rodizio|secuencia|degustacion|acompanamientos|guarniciones/.test(texto);
    if (intencion === 'pizza')
        return tipos.includes('pizza') || /italian|pasta|risotto|pizzeria/.test(texto);
    if (intencion === 'asiatica')
        return tipos.includes('asiatica') || /sushi|japones|nikkei|omakase|chino|corean|tailandes|panasiatic/.test(texto);
    if (intencion === 'carioca')
        return tipos.some(t => ['carioca', 'nordestina'].includes(t)) || /brasilen|brasileir|boteco|feijoada|baiana/.test(texto);
    return tipos.includes(intencion) || texto.includes(normalizarBusquedaGastronomica(intencion));
};
const textoBusquedaGastronomica = item => normalizarBusquedaGastronomica(`${item.nombre} ${item.barrio} ${item.zona} ${item.destaque} ${(item.tipos || []).join(' ')} ${(item.tipos || []).map(t => NOMBRES_TIPOS_GASTRONOMICOS[t] || '').join(' ')}`);
