function ECTranslateConsejosTree(root, lang) {
    if (!root || lang === 'es') return;
    const dict = (window.GLOBAL_UI_TRANSLATIONS && window.GLOBAL_UI_TRANSLATIONS[lang]) || {};
    const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
    const nodes=[]; while(walker.nextNode()) nodes.push(walker.currentNode);
    nodes.forEach(n=>{ const raw=n.nodeValue||''; const t=raw.trim(); if(t && dict[t]) n.nodeValue=raw.replace(t,dict[t]); });
    root.querySelectorAll('[alt],[title],[placeholder],[aria-label]').forEach(el=>['alt','title','placeholder','aria-label'].forEach(a=>{const v=el.getAttribute(a); if(v && dict[v]) el.setAttribute(a,dict[v]);}));
}
function ECUseConsejosTranslation(lang, dep) {
    const ref=React.useRef(null);
    React.useEffect(()=>{ const id=requestAnimationFrame(()=>ECTranslateConsejosTree(ref.current,lang)); return ()=>cancelAnimationFrame(id); },[lang,dep]);
    return ref;
}
