React.createElement = function (type, props, ...children) {
    let next = props;
    if (type === 'img') {
        next = { ...(props || {}) };
        if (!next.loading)
            next.loading = 'lazy';
        if (!next.decoding)
            next.decoding = 'async';
    }
    else if (type === 'iframe') {
        next = { ...(props || {}) };
        if (!next.loading)
            next.loading = 'lazy';
    }
    return __v45ReactCreateElement.call(React, type, next, ...children);
};
function v45CloudinaryVariant(url, width = 720) {
    const u = String(url || '');
    if (!u.includes('res.cloudinary.com') || !u.includes('/image/upload/'))
        return u;
    return u.replace('/image/upload/', '/image/upload/f_auto,q_auto,w_' + width + ',c_limit/');
}
